import {escapeHtml as esc,icon} from './components.js';
import {PERIODS,dollars,pct,tone,at,ret,loadStars,saveStars} from './crypto-format.js';
import {mountCryptoChart} from './crypto-chart.js';
import {renderCryptoMap} from './crypto-map.js';

export function mountCrypto(root,{navigate}){
 const initial=new URLSearchParams(location.search),demo=initial.get('demo')==='1';
 let data,period=initial.get('period')||'day',method=initial.get('method')||'equal',filter=initial.get('field')||'',sort=initial.get('sort')||'return',selected=decodeURIComponent(location.pathname.split('/')[2]||initial.get('coin')||''),focus=null,scale=1,onlyStars=false,stars=loadStars(demo),version=0,abort,dead=false,timer;
 if(![...PERIODS.map(p=>p[0]),'custom'].includes(period))period='day';
 root.innerHTML=`<div class="page-heading"><div><div class="eyebrow">DIGITAL ASSETS</div><h1>가상자산</h1></div><div class="crypto-status"><span>연결 확인 중</span><button class="icon-button" data-crypto-refresh aria-label="가상자산 새로고침">${icon('refresh')}</button></div></div><div class="crypto-demo" ${demo?'':'hidden'}>샘플 데이터 · 실제 시세가 아닙니다. <a href="/crypto" data-nav>실제 데이터 보기 →</a></div><div class="crypto-notice" role="status"></div><section class="crypto-overview" aria-label="코인 시장 요약"></section><section class="crypto-majors" aria-label="주요 코인"></section><section class="surface crypto-controls"><div class="crypto-periods" role="group" aria-label="코인 수익률 기간">${PERIODS.map(([id,label])=>`<button data-period="${id}" aria-pressed="${period===id}">${label}</button>`).join('')}<button data-period="custom" aria-pressed="${period==='custom'}">직접 선택</button></div><div class="crypto-dates" ${period==='custom'?'':'hidden'}><label>시작일 <input type="date" class="crypto-start" value="${esc(initial.get('start')||'')}"></label><label>종료일 <input type="date" class="crypto-end" value="${esc(initial.get('end')||'')}"></label><button class="secondary-button" data-apply-dates>기간 적용</button></div><small class="crypto-history-note"></small></section><div class="crypto-workspace"><section class="surface crypto-list"><div class="panel-heading"><div class="title-group"><h2>코인 목록</h2><span class="crypto-count"></span></div><button data-stars-only aria-pressed="false">☆ 관심코인</button></div><div class="crypto-list-filters"><label class="crypto-search">${icon('search')}<input type="search" placeholder="코인명·티커 검색" aria-label="코인명·티커 검색"></label><select class="crypto-field" aria-label="코인 분야"><option value="">전체 분야</option></select><select class="crypto-sort" aria-label="코인 정렬"><option value="return">상승률순</option><option value="losers">하락률순</option><option value="cap">시가총액순</option><option value="price">가격순</option><option value="name">이름순</option></select></div><div class="crypto-table-wrap"><table class="crypto-table"><thead><tr><th>관심</th><th>코인</th><th>현재가 · USD</th><th class="crypto-return-header">일간 수익률</th><th>분야</th></tr></thead><tbody></tbody></table><div class="crypto-list-state crypto-empty">코인 시세를 불러오고 있어요</div></div><div class="panel-foot crypto-list-foot"></div></section><section class="surface crypto-detail" aria-label="선택 코인 상세"><div class="crypto-detail-head"></div><div class="crypto-detail-numbers"></div><div class="crypto-chart"></div><div class="crypto-detail-meta"></div></section></div><div class="crypto-analysis-grid"><section class="surface crypto-fields"><div class="panel-heading"><h2>분야 순위</h2><select class="crypto-weight" aria-label="분야 수익률 계산 방식"><option value="equal">동일가중 평균</option><option value="cap">시가총액 가중</option></select></div><p class="crypto-method-note"></p><div class="crypto-sector-rows"></div><div class="crypto-fields-foot"></div></section><section class="surface crypto-map-card"><div class="panel-heading"><h2>분야맵</h2><div class="crypto-map-buttons"><button data-map-back hidden>전체 분야</button><button data-map-full>${icon('expand')} 확대</button></div></div><div class="crypto-map-host"></div><div class="crypto-map-legend"><span class="negative">−10% 이하</span><i></i><span class="up">+10% 이상</span><span>사선: 수익률 없음</span></div><p class="crypto-map-note"></p></section></div><footer class="crypto-footer"></footer><dialog class="crypto-map-dialog"><div class="panel-heading"><h2>가상자산 분야맵</h2><div class="crypto-map-buttons"><button data-map-back>전체 분야</button><button data-map-minus aria-label="맵 축소">−</button><button data-map-plus aria-label="맵 확대">+</button><button data-map-close aria-label="분야맵 닫기">닫기 ✕</button></div></div><p class="crypto-full-caption"></p><div class="crypto-full-map"></div></dialog>`;
 const $=s=>root.querySelector(s),chart=mountCryptoChart($('.crypto-chart'),{demo}),dialog=$('.crypto-map-dialog');$('.crypto-sort').value=sort;$('.crypto-weight').value=method;
 const periodLabel=()=>PERIODS.find(p=>p[0]===period)?.[1]||'선택 기간';
 function query(){return new URLSearchParams({period,method,...(demo?{demo:'1'}:{}),...(period==='custom'?{start:$('.crypto-start').value,end:$('.crypto-end').value}:{})});}
 function saveUrl(){const q=query();if(filter)q.set('field',filter);q.set('sort',sort);if(selected)q.set('coin',selected);history.replaceState({},'',location.pathname+'?'+q);}
 function star(c){const on=stars.has(c.id);return `<button class="crypto-star ${on?'on':''}" data-star="${esc(c.id)}" aria-pressed="${on}" aria-label="${on?'관심코인 해제':'관심코인 추가'}" title="${on?'관심코인 해제':'관심코인 추가'}">${on?'★':'☆'}</button>`;}
 async function refresh(){const mine=++version;abort?.abort();abort=new AbortController();$('.crypto-status span').textContent='갱신 중';try{const response=await fetch('/api/crypto?'+query(),{signal:abort.signal});const next=await response.json();if(mine!==version||dead)return;if(!response.ok||next.status!=='ready')throw new Error(next.message||'데이터 없음');data=next;render();}catch(e){if(mine!==version||dead||e.name==='AbortError')return;$('.crypto-status span').textContent=data?'갱신 지연':'연결 필요';$('.crypto-notice').textContent=e.message+(data?' · 마지막 정상 데이터를 표시합니다.':'');if(!data){$('.crypto-list-state').textContent='코인 데이터를 불러오지 못했습니다.';$('.crypto-detail-head').innerHTML='<h2>데이터 연결 필요</h2>';$('.crypto-sector-rows').innerHTML='<div class="crypto-empty">분야 데이터 없음</div>';$('.crypto-map-host').innerHTML='<div class="crypto-empty">코인 데이터 없음</div>';}}finally{clearTimeout(timer);if(!dead)timer=setTimeout(()=>{if(!document.hidden)refresh();else schedule();},30000);}}
 function schedule(){timer=setTimeout(()=>{if(!document.hidden)refresh();else schedule();},30000);}
 function render(){
  const values=data.items.map(c=>ret(c,period)).filter(Number.isFinite),avg=values.length?values.reduce((a,b)=>a+b,0)/values.length:null;
  $('.crypto-status span').textContent=demo?'샘플 데이터':data.stale?'갱신 지연':'주기적 갱신 · '+Math.round(data.intervalSeconds/60)+'분';
  $('.crypto-notice').textContent=[data.message,data.metadata?.progress,data.metadata?.error,data.metadata?.stale&&data.categories.length?'분야 정보 갱신 지연':null].filter(Boolean).join(' · ');
  $('.crypto-overview').innerHTML=`<div><small>Finviz 제공 코인 전체 요약</small><strong>${data.items.length}<em>개 코인</em></strong></div><div><small>${periodLabel()} 동일가중 평균</small><strong class="${tone(avg)}">${pct(avg)}</strong></div><div><small>상승 / 하락</small><strong><span class="up">${values.filter(v=>v>0).length}</span><em>/</em><span class="negative">${values.filter(v=>v<0).length}</span></strong></div><div><small>마지막 수신</small><b>${at(data.receivedAt)}</b><small>시세 체결 시각 미제공</small></div>`;
  $('.crypto-majors').innerHTML=['BTC','ETH','SOL'].map(symbol=>data.items.find(c=>c.symbol===symbol)).filter(Boolean).map(c=>`<button class="surface crypto-major" data-coin="${esc(c.id)}"><span class="crypto-coin-icon">${esc(c.symbol.slice(0,1))}</span><div><b>${esc(c.name)} <small>${esc(c.symbol)}</small></b><strong>${dollars(c.price)}</strong></div><span class="${tone(ret(c,'day'))}">${pct(ret(c,'day'))}<small>일간 · ${at(c.receivedAt)}</small></span></button>`).join('');
  $('.crypto-field').innerHTML='<option value="">전체 분야</option>'+data.categories.map(c=>`<option value="${esc(c.id)}">${esc(c.label)} · ${esc(c.name)}</option>`).join('')+'<option value="unclassified">미분류</option>';$('.crypto-field').value=filter;
  const h=data.history;$('.crypto-history-note').textContent=`가격·수익률: Finviz · 일간은 공급사의 Day 기준(24시간 수익률로 재해석하지 않음). 저장 가격: ${h?.first||'없음'}${h?.last?' ~ '+h.last:''} · 직접 선택은 KST 해당일 최초 저장가 기준.`;
  for(const input of [$('.crypto-start'),$('.crypto-end')]){input.min=h?.first||'';input.max=h?.last||'';}if(!$('.crypto-start').value)$('.crypto-start').value=h?.first||'';if(!$('.crypto-end').value)$('.crypto-end').value=h?.last||'';
  const customButton=root.querySelector('[data-period="custom"]');customButton.disabled=!h?.first||h.first===h.last;customButton.title=customButton.disabled?'서로 다른 날짜의 저장 가격이 필요합니다.':'';
  if(!data.items.some(c=>c.id===selected))selected=data.items.find(c=>c.symbol==='BTC')?.id||data.items[0]?.id;
  renderRows();renderDetail();renderFields();renderMaps();$('.crypto-footer').textContent=`가격·수익률: Finviz Elite Crypto Performance · 분야·시가총액: CoinMarketCap · USD · 시세 수신 ${at(data.receivedAt)} · 분류 수집 ${at(data.metadata?.receivedAt)}. 전체 가상자산 시장을 대표하는 지수는 아닙니다.`;
 }
 function renderRows(){if(!data)return;const q=$('.crypto-search input').value.toLowerCase().replace(/\s/g,'');let rows=data.items.filter(c=>(!q||(c.name+c.symbol+c.ticker).toLowerCase().replace(/\s/g,'').includes(q))&&(!onlyStars||stars.has(c.id))&&(!filter||(filter==='unclassified'?!c.categories.length:c.categories.some(s=>s.id===filter))));rows.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='price'?b.price-a.price:sort==='cap'?(b.marketCap??-Infinity)-(a.marketCap??-Infinity):sort==='losers'?(ret(a,period)??Infinity)-(ret(b,period)??Infinity):(ret(b,period)??-Infinity)-(ret(a,period)??-Infinity));
  $('.crypto-list h2').textContent=filter?(data.categories.find(c=>c.id===filter)?.label||'미분류')+' 코인':'코인 목록';$('.crypto-count').textContent=rows.length+' / '+data.items.length;$('.crypto-return-header').textContent=periodLabel()+' 수익률';$('.crypto-list-state').hidden=!!rows.length;$('.crypto-list-state').textContent=onlyStars?'등록한 관심코인이 없습니다. 별표를 눌러 추가하세요.':'조건에 맞는 코인이 없습니다.';
  $('.crypto-table tbody').innerHTML=rows.map(c=>`<tr data-row="${esc(c.id)}" tabindex="0" class="${c.id===selected?'selected':''}" aria-label="${esc(c.name)} 코인 상세 선택"><td>${star(c)}</td><td><button data-coin="${esc(c.id)}" class="crypto-name"><b>${esc(c.name)}</b><small>${esc(c.symbol)}</small></button></td><td>${dollars(c.price)}</td><td class="${tone(ret(c,period))}">${pct(ret(c,period))}</td><td><span class="crypto-field-chip">${esc(c.primary?.label||'미분류')}</span>${c.categories.length>1?`<small>+${c.categories.length-1}</small>`:''}</td></tr>`).join('');$('.crypto-list-foot').textContent='Finviz 제공 '+data.items.length+'개 중 '+rows.length+'개 · 수신 '+at(data.receivedAt)+(data.stale?' · 갱신 지연':'');
 }
 function renderDetail(){const c=data?.items.find(c=>c.id===selected);if(!c)return;$('.crypto-detail-head').innerHTML=`<div><small>코인 상세 · ${esc(c.symbol)}</small><h2>${esc(c.name)}</h2></div>${star(c)}`;$('.crypto-detail-numbers').innerHTML=`<strong>${dollars(c.price)} <small>USD</small></strong><span class="${tone(ret(c,period))}">${pct(ret(c,period))} <small>${periodLabel()}</small></span><div class="crypto-return-grid">${PERIODS.slice(0,6).map(([id,label])=>`<div><small>${label}</small><b class="${tone(ret(c,id))}">${pct(ret(c,id))}</b></div>`).join('')}</div>`;
  chart.select(c.id,c.receivedAt);$('.crypto-detail-meta').innerHTML=`<div class="crypto-detail-fields">${c.categories.map(s=>`<button data-field="${esc(s.id)}">${esc(s.label)}</button>`).join('')||'<span class="crypto-field-chip">미분류</span>'}</div><p>Finviz 수신 ${at(c.receivedAt)} · 주기적 조회</p>${c.marketCap?`<p>시가총액 ${dollars(c.marketCap,true)} · CMC 기준 ${at(c.capAsOf)}</p>`:''}${c.customBasis?`<p>시작 ${dollars(c.customBasis.startPrice)} · ${at(c.customBasis.startAt)}<br>종료 ${dollars(c.customBasis.endPrice)} · ${at(c.customBasis.endAt)}</p>`:''}${!c.cmcId?`<p>분류 연결: ${esc(c.mappingReason||'CMC 정보 없음')}</p>`:''}<a href="/crypto/${encodeURIComponent(c.id)}?${query()}" data-nav>이 코인 링크 열기 →</a>`;
 }
 function renderFields(){const rows=data.sectors||[];$('.crypto-method-note').textContent=method==='cap'?'CMC 현재 시가총액 가중 · Finviz 수익률. 시총이 모두 연결된 분야만 계산합니다.':'Finviz 수익률의 동일가중 평균 · 선택 기간 결측값 제외';$('.crypto-sector-rows').innerHTML=rows.length?rows.map((s,i)=>`<button class="crypto-sector-row" data-field="${esc(s.id)}"><span class="crypto-sector-rank">${s.value===null?'—':i+1}</span><span><b>${esc(s.label)}</b><small>${esc(s.name)}</small><small>상승 ${s.rising} · 하락 ${s.falling} · ${s.count}/${s.available}개 계산</small></span><span class="${tone(s.value)}"><b>${pct(s.value)}</b><small>${s.reason?esc(s.reason):s.leaders.map(c=>esc(c.symbol)+' '+(c.contribution>=0?'+':'')+c.contribution.toFixed(2)+'%p').join(' · ')}</small></span></button>`).join(''):'<div class="crypto-empty">분야 데이터 연결 후 순위를 표시합니다.</div>';
  $('.crypto-fields-foot').textContent='기여값 = 코인 수익률 × 선택 가중치 · 한 코인은 여러 분야에 포함될 수 있습니다. 분야 성과를 합산하지 않습니다.';
 }
 function renderMaps(){if(!data)return;renderCryptoMap($('.crypto-map-host'),data.items,period,focus);if(dialog.open)renderCryptoMap($('.crypto-full-map'),data.items,period,focus,scale);root.querySelectorAll('[data-map-back]').forEach(b=>b.hidden=!focus);$('.crypto-map-note').textContent=`Finviz ${data.items.length}개 · 분야 → 코인 · 면적: CMC 시가총액 · 대표 분야 하나만 배치. 대표 분야: 스테이블 → 밈 → AI → 게임 → RWA → DeFi → L2 → L1 순. 결측 시총은 아래에 동일 크기로 표시합니다.`;$('.crypto-full-caption').textContent=periodLabel()+' · '+(method==='cap'?'시가총액 가중':'동일가중')+' · 수신 '+at(data.receivedAt);}
 function select(id,scroll=false){selected=id;saveUrl();renderRows();renderDetail();if(scroll&&matchMedia('(max-width: 900px)').matches)$('.crypto-detail').scrollIntoView({behavior:'smooth',block:'start'});}
 function onClick(e){
  const starButton=e.target.closest('[data-star]');if(starButton){e.preventDefault();e.stopPropagation();const id=starButton.dataset.star;stars.has(id)?stars.delete(id):stars.add(id);try{saveStars(stars,demo);}catch{$('.crypto-notice').textContent='브라우저 저장소를 사용할 수 없습니다.';}return;}
  const b=e.target.closest('button');if(b?.hasAttribute('data-crypto-refresh'))refresh();
  if(b?.dataset.period){period=b.dataset.period;root.querySelectorAll('[data-period]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('.crypto-dates').hidden=period!=='custom';if(period!=='custom'){saveUrl();refresh();}}
  if(b?.hasAttribute('data-apply-dates')){saveUrl();refresh();}
  if(b?.hasAttribute('data-stars-only')){onlyStars=!onlyStars;b.setAttribute('aria-pressed',onlyStars);renderRows();}
  if(b?.dataset.field){filter=filter===b.dataset.field?'':b.dataset.field;$('.crypto-field').value=filter;focus=filter||null;saveUrl();renderRows();renderMaps();}
  if(b?.dataset.mapSector){focus=b.dataset.mapSector;filter=focus;$('.crypto-field').value=filter;saveUrl();renderRows();renderMaps();}
  if(b?.hasAttribute('data-map-back')){focus=null;filter='';$('.crypto-field').value='';scale=1;saveUrl();renderRows();renderMaps();}
  if(b?.hasAttribute('data-map-full')){dialog.showModal();renderMaps();}
  if(b?.hasAttribute('data-map-close'))dialog.close();
  if(b?.hasAttribute('data-map-plus')){scale=Math.min(3,scale+.25);renderMaps();}
  if(b?.hasAttribute('data-map-minus')){scale=Math.max(1,scale-.25);renderMaps();}
  if(b?.dataset.coin){if(dialog.open)dialog.close();select(b.dataset.coin,true);return;}
  const row=e.target.closest('[data-row]');if(row)select(row.dataset.row);
 }
 root.addEventListener('click',onClick);
 const onKey=e=>{if(e.target.matches('[data-row]')&&['Enter',' '].includes(e.key)){e.preventDefault();select(e.target.dataset.row,true);}};root.addEventListener('keydown',onKey);
 $('.crypto-search input').addEventListener('input',renderRows);
 $('.crypto-field').addEventListener('change',e=>{filter=e.target.value;saveUrl();renderRows();});$('.crypto-sort').addEventListener('change',e=>{sort=e.target.value;saveUrl();renderRows();});$('.crypto-weight').addEventListener('change',e=>{method=e.target.value;saveUrl();refresh();});
 const sync=()=>{stars=loadStars(demo);renderRows();renderDetail();};addEventListener('storage',sync);addEventListener('crypto-watch-change',sync);
 const observer=new ResizeObserver(()=>{if(data)renderMaps();});observer.observe($('.crypto-map-card'));
 refresh();return {destroy(){dead=true;clearTimeout(timer);++version;abort?.abort();chart.destroy();observer.disconnect();root.removeEventListener('click',onClick);root.removeEventListener('keydown',onKey);removeEventListener('storage',sync);removeEventListener('crypto-watch-change',sync);dialog.close();root.innerHTML='';}};
}
